const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const COMPONENT_BASE = 25;
const COMPONENT_BLOCK_BASE = 60;
const COMPONENT_BLOCK_SIZE = 3;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

type Item = { type: string };
type Step = { op: "quote"; items: Item[] };
type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };

const basePremiumForComponentCount = (count: number): number =>
  count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_BASE : count * COMPONENT_BASE;

const countByType = (items: Item[]): Map<string, number> =>
  items.reduce(
    (counts, { type }) => counts.set(type, (counts.get(type) ?? 0) + 1),
    new Map<string, number>(),
  );

const basePremiumForType = (type: string, count: number): number =>
  COMPONENT_TYPES.has(type) ? basePremiumForComponentCount(count) : count * BASE_PREMIUM[type];

const basePremiumFor = (items: Item[]): number =>
  Array.from(countByType(items)).reduce(
    (sum, [type, count]) => sum + basePremiumForType(type, count),
    0,
  );

const roundInMHPCOsFavor = (premium: number): number => Math.ceil(premium);

const withFirstInsuranceSurcharge = (base: number): number =>
  base + base * FIRST_INSURANCE_SURCHARGE_RATE;

const quotePremium = (step: Step): number =>
  roundInMHPCOsFavor(withFirstInsuranceSurcharge(basePremiumFor(step.items))) + PROCESSING_FEE;

export const runScenario = (scenario: Scenario): { results: Array<{ premium: number }> } => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
});

