import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Empty and basic quote ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });
    expect(result).toEqual({ results: [{ premium: 5 }] });
  });
  it("quote for a single plain sword (0 years, first insurance) → 100 + 10 (first) + 5 fee = 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("quote for a single plain amulet → 60 base + 6 first + 5 fee = 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("quote for a single plain staff → 80 base + 8 first + 5 fee = 93 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("quote for a single plain potion → 40 base + 4 first + 5 fee = 49 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Component pricing ---
  it("2 runes → 50 G base premium → 60 G total (50 + 5 first + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
  it("3 runes → 60 G base (block applies) → 71 G total (60 + 6 first + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("4 runes → 100 G base (no block) → 115 G total (100 + 10 + 5)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("7 runes → 175 G base premium (block of 3 + 4 singles) → 175 + 18 first + 5 fee = 198 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
          ],
        },
      ],
    });
    expect(result).toEqual({ results: [{ premium: 198 }] });
  });
  it("2 runes + 1 moonstone → 75 G base premium (no block: different types) → 75 + 8 first + 5 fee = 88 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    });
    expect(result).toEqual({ results: [{ premium: 88 }] });
  });
  it("3 runes + 3 moonstones → 120 G base premium (two separate blocks) → 120 + 12 first + 5 fee = 137 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "moonstone" },
            { type: "moonstone" },
            { type: "moonstone" },
          ],
        },
      ],
    });
    expect(result).toEqual({ results: [{ premium: 137 }] });
  });

  // --- Item-specific modifiers ---
  it("cursed sword + plain amulet → 160 base + 50 curse + 16 first (10% of 160) + 5 fee = 231 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", cursed: true },
            { type: "amulet" },
          ],
        },
      ],
    });
    expect(result).toEqual({ results: [{ premium: 231 }] });
  });
  it.todo("sword with enchantment exactly 5 → high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("sword with enchantment 5 AND cursed → both surcharges apply");

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years → loyalty discount (20%) applies");
  it.todo("customer with 1 year → no loyalty discount");
  it.todo("first insurance surcharge of 10% applies per item as first insurance");
  it.todo("follow-up contract (customer's second quote in scenario) receives 15% discount on the policy");

  // --- Rounding (in MHPCO's favor) ---
  it.todo("premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
  it.todo("payout calculation yielding 350.5 G → final payout 350 G (rounded down)");

  // --- Integration examples from spec ---
  it.todo("newcomer with a cursed sword (0 years, no previous) → 165 G");
  it.todo("long-standing customer's second contract with cursed sword enchantment 7 → 160 G");

  // --- Claim: basic reimbursement ---
  it.todo("regular sword damage 500 G → payout 400 G (500 - 100 deductible)");
  it.todo("rune damage 200 G → payout 100 G (200 - 100 deductible; no special clause)");

  // --- Claim: special clauses ---
  it.todo("enchantment-8 dragon-material sword, damage 1000 G → payout 400 G (50% then deductible)");
  it.todo("enchantment-9 dragon-material sword, damage 1000 G → payout 400 G (both apply, 50% wins)");
  it.todo("dragon-material sword enchantment 5, damage 800 G → payout 700 G (dragon full, then deductible)");
  it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G (high enchantment 50%, then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 G (deductible applied per item)");

  // --- Claim: multiple items of same type ---
  it.todo("policy covers two swords → insurance sum 2000 G, cap 4000 G; dragon attack damages both → each damage handled separately");
  it.todo("damages array has more entries of a type than policy covers → CLI exits non-zero");

  // --- Claim: cap exhaustion ---
  it.todo("sword + amulet policy → insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword (premium 165 G) → cap 2000 G (based on unmodified insurance value)");
  it.todo("sword + 3 runes (block) → insurance sum 1750 G (block discount does not affect insurance sum)");
  it.todo("sword insured (cap 2000 G); two successive claims of 1500 G each → first payout 1400 G, second payout 600 G");

  // --- Edge cases ---
  it.todo("quote with unknown item type → CLI exits non-zero, writes error to stderr, no results on stdout");
  it.todo("claim references item not in policy (amulet damage when only sword insured) → CLI exits non-zero");
  it.todo("claim with damage amount -200 → CLI exits non-zero");

  // --- Multi-step scenario ---
  it.todo("scenario with quote then claim on that policy returns results array of matching length and order");
});

