35	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
36	    ? COMPONENT_BLOCK_BASE
37	    : count * BASE_PREMIUM[type];
38	
39	const basePremiumForItems = (items: Item[]): number =>
40	  [...countByType(items)].reduce(
41	    (sum, [type, count]) => sum + basePremiumForGroup(type, count),
42	    0,
43	  );
44	
45	const surchargeRateForItem = (item: Item): number =>
46	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
47	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
48	
49	const itemSurcharges = (items: Item[]): number =>
50	  items.reduce(
51	    (sum, item) => sum + BASE_PREMIUM[item.type] * surchargeRateForItem(item),
52	    0,
53	  );
54	
55	const roundInMHPCOsFavor = (premium: number): number => Math.ceil(premium);
56	
57	const loyaltyDiscountRate = (customer: Customer): number =>
58	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? LOYALTY_DISCOUNT_RATE : 0;
59	
60	const followupDiscountRate = (quoteIndex: number): number =>
61	  quoteIndex > 0 ? FOLLOWUP_CONTRACT_DISCOUNT_RATE : 0;
62	
63	const withPolicyWideModifiers = (
64	  base: number,
65	  customer: Customer,
66	  quoteIndex: number,
67	): number =>
68	  base +
69	  base * FIRST_INSURANCE_SURCHARGE_RATE -
70	  base * loyaltyDiscountRate(customer) -
71	  base * followupDiscountRate(quoteIndex);
72	
73	const quotePremium = (
74	  { items }: Step,
75	  customer: Customer,
76	  quoteIndex: number,
77	): number =>
78	  roundInMHPCOsFavor(
79	    withPolicyWideModifiers(basePremiumForItems(items), customer, quoteIndex) +
80	      itemSurcharges(items),
81	  ) + PROCESSING_FEE;
82	
83	const priorQuoteCount = (steps: Step[], upToIndex: number): number =>
84	  steps.slice(0, upToIndex).filter((step) => step.op === "quote").length;
85	
