const LOYALTY_DISCOUNT_RATE = 0.2;
const LOYALTY_THRESHOLD_YEARS = 2;
const FOLLOWUP_CONTRACT_DISCOUNT_RATE = 0.15;
const COMPONENT_BLOCK_BASE = 60;
const COMPONENT_BLOCK_SIZE = 3;
const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLIER = 2;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const INSURANCE_VALUE: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

type Item = { type: string; cursed?: boolean; enchantment?: number; material?: string };
type Customer = { yearsWithMHPCO: number };
type QuoteStep = { op: "quote"; items: Item[] };
type Damage = { itemType: string; amount: number };
type ClaimStep = {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
};
type Step = QuoteStep | ClaimStep;
type Scenario = { customer: Customer; steps: Step[] };

type QuoteResult = { premium: number };
type ClaimResult = { payout: number; remainingCap: number };
type StepResult = QuoteResult | ClaimResult;

type Policy = { items: Item[]; insuranceSum: number; cap: number; remainingCap: number };

const countByType = (items: Item[]): Map<string, number> =>
  items.reduce(
    (counts, { type }) => counts.set(type, (counts.get(type) ?? 0) + 1),
    new Map<string, number>(),
  );

const basePremiumForGroup = (type: string, count: number): number =>
  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_BASE
    : count * BASE_PREMIUM[type];

const basePremiumForItems = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (sum, [type, count]) => sum + basePremiumForGroup(type, count),
    0,
  );

const surchargeRateForItem = (item: Item): number =>
  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);

const itemSurcharges = (items: Item[]): number =>
  items.reduce(
    (sum, item) => sum + BASE_PREMIUM[item.type] * surchargeRateForItem(item),
    0,
  );

const roundUpForInsurer = (premium: number): number => Math.ceil(premium);
const roundDownForInsurer = (payout: number): number => Math.floor(payout);

const loyaltyDiscountRate = (customer: Customer): number =>
  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? LOYALTY_DISCOUNT_RATE : 0;

const followupDiscountRate = (quoteIndex: number): number =>
  quoteIndex > 0 ? FOLLOWUP_CONTRACT_DISCOUNT_RATE : 0;

const withPolicyWideModifiers = (
  base: number,
  customer: Customer,
  quoteIndex: number,
): number =>
  base +
  base * FIRST_INSURANCE_SURCHARGE_RATE -
  base * loyaltyDiscountRate(customer) -
  base * followupDiscountRate(quoteIndex);

const quotePremium = (
  { items }: QuoteStep,
  customer: Customer,
  quoteIndex: number,
): number =>
  roundUpForInsurer(
    withPolicyWideModifiers(basePremiumForItems(items), customer, quoteIndex) +
      itemSurcharges(items),
  ) + PROCESSING_FEE;

const insuranceSumFor = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);

const policyFrom = (items: Item[]): Policy => {
  const insuranceSum = insuranceSumFor(items);
  const cap = insuranceSum * CAP_MULTIPLIER;
  return { items, insuranceSum, cap, remainingCap: cap };
};

const payoutForDamage = (amount: number): number =>
  roundDownForInsurer(Math.max(0, amount - DEDUCTIBLE_PER_DAMAGE));

const totalPayoutFor = (damages: Damage[]): number =>
  damages.reduce((sum, damage) => sum + payoutForDamage(damage.amount), 0);

const applyClaim = (
  policy: Policy,
  step: ClaimStep,
): { policy: Policy; result: ClaimResult } => {
  const payout = Math.min(totalPayoutFor(step.incident.damages), policy.remainingCap);
  const remainingCap = policy.remainingCap - payout;
  return { policy: { ...policy, remainingCap }, result: { payout, remainingCap } };
};

export const runScenario = ({ customer, steps }: Scenario): { results: StepResult[] } => {
  const results: StepResult[] = [];
  const policies = new Map<number, Policy>();
  let quoteIndex = 0;
  steps.forEach((step, index) => {
    if (step.op === "quote") {
      results.push({ premium: quotePremium(step, customer, quoteIndex) });
      policies.set(index, policyFrom(step.items));
      quoteIndex += 1;
    } else {
      const { policy, result } = applyClaim(policies.get(step.policy)!, step);
      policies.set(step.policy, policy);
      results.push(result);
    }
  });
  return { results };
};

