147	      results.push({ premium: quotePremium(step, customer, policies.size) });
148	      policies.set(index, policyFrom(step.items));
149	    } else {
150	      const { policy, result } = applyClaim(policies.get(step.policy)!, step);
151	      policies.set(step.policy, policy);
152	      results.push(result);
153	    }
154	  });
155	  return { results };
156	};
